"""Render reviewed numeric tables and machine-readable final analysis packet."""
import csv, hashlib, json
from pathlib import Path
R=Path(__file__).resolve().parents[1];O=R/'reports';A=O/'analysis_20260928'
def js(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def rows(p):return list(csv.DictReader(p.open(encoding='utf-8',newline='')))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def mdtable(headers,data):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(str(v) for v in r)+' |' for r in data])
def writejson(name,data):(O/name).write_text(json.dumps(data,indent=2,ensure_ascii=False,allow_nan=False)+'\n',encoding='utf-8')

control=rows(A/'control_all_methods.csv');lat=rows(A/'latency_pooled_descriptive.csv');seedlat=rows(A/'latency_per_seed.csv')
cm=js(R/'evidence/confirmatory_checkpoint_manifest_v3.json');ca=js(R/'evidence/locked_test_analysis_v3.json');la=js(R/'evidence/latency_analysis_v3.json');audit=js(A/'audit.json')
lookup={(r['role'],r['pde'],r['method']):r for r in control}
methods=('B0','B1','B2','B3','B4','B5','P-no-rank','P')
g2=[]
for pde in ('burgers','heat'):
 for m in ('P','P-no-rank','B4','B5'):
  rr=[r for r in cm['checkpoints'] if r['pde']==pde and r['method']==m]
  g2.append([pde,m,*[f"{r['metadata']['validation']['validation_field_nrmse']:.5f}" for r in rr],'FAIL (all seeds)'])
nom=[]
for m in methods:
 b=lookup['locked_nominal','burgers',m];h=lookup['locked_nominal','heat',m]
 nom.append([m,f"{float(b['mean_cost']):.6f}",f"{float(b['tracking_rmse']):.6f}",f"{100*float(b['relative_cost_difference_vs_B0']):+.2f}%",f"{float(h['mean_cost']):.6f}",f"{float(h['tracking_rmse']):.6f}",f"{100*float(h['relative_cost_difference_vs_B0']):+.2f}%"])
shift=[]
for m in methods:
 shift.append([m,*[f"{100*float(lookup[role,pde,m]['relative_cost_difference_vs_B0']):+.2f}%" for role,pde in [('locked_coefficient_ood','burgers'),('locked_coefficient_ood','heat'),('locked_delay_dropout','burgers'),('locked_delay_dropout','heat')]]])
lattable=[]
for pde in ('burgers','heat'):
 for m in methods:
  r=next(r for r in lat if r['pde']==pde and r['method']==m)
  lattable.append([pde,m,'CPU' if m in ('B0','B1') else 'CUDA',f"{float(r['p50_ms']):.3f}",f"{float(r['p99_ms']):.3f}",f"{int(r['miss_count_5ms']):,}/{int(r['n_requests']):,}",f"{100*float(r['miss_rate_5ms']):.3f}%"])
seedtable=[]
for r in seedlat:
 seedtable.append([r['pde'],r['method'],r['seed'] or 'na',*[f"{float(r[k]):.4f}" for k in ('p50_ms','p95_ms','p99_ms','p999_ms')],r['misses_5ms'],f"{100*float(r['deadline_miss_rate_5ms']):.4f}%"])
hash_files=['evidence/raw_evidence_freeze_v3.json','evidence/locked_test_analysis_v3.json','evidence/latency_summary_v3.json','evidence/latency_analysis_v3.json','evidence/confirmatory_checkpoint_manifest_v3.json','evidence/calibration_lock_v3.json','config/final_spec_v3.json','evidence/cuda_runtime_assessment_v3.json','evidence/cuda_runtime_assessment_v3_corrected.json','AUTHOR_INPUT_REQUIRED.md']
hashes=[{'path':f,'sha256':sha(R/f)} for f in hash_files]
commands=[('Train required families','run_confirmatory_models_v3.py'),('Freeze model selection','freeze_checkpoint_manifest_v3.py'),('Select H3 comparator','select_validation_comparator_v3.py'),('Generate calibration trajectories','generate_calibration_data_v3.py'),('Generate calibration queries','generate_calibration_queries_v3.py'),('Freeze passive forecast margins','calibrate_forecast_margins_v3.py'),('Generate fresh locked parents','generate_locked_data_v3.py'),('Freeze locked evaluation inputs','freeze_locked_evaluation_v3.py'),('One-shot locked evaluation','run_locked_test_once_v3.py'),('Registered test aggregate','aggregate_locked_test_v3.py'),('Registered host replay','benchmark_host_e2e_v3.py'),('Registered latency analysis','analyze_latency_v3.py'),('Final raw freeze','freeze_raw_evidence_v3.py')]
command_rows=[{'stage':label,'command':f"& '.venv/Scripts/python.exe' 'scripts/{script}'",'script_sha256':sha(R/'scripts'/script),'current_task_executed':False,'evidence':'Historical ledger and source entry point; see supervisor receipt for locked runner'} for label,script in commands]
with (O/'historical_commands.csv').open('w',encoding='utf-8',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(command_rows[0]));w.writeheader();w.writerows(command_rows)
tables={'G2_TABLE':mdtable(['PDE','Method','seed 11','seed 23','seed 37','nRMSE ≤0.05'],g2),'NOMINAL_TABLE':mdtable(['Method','Burgers cost','Burgers RMSE','Cost vs B0','Heat cost','Heat RMSE','Cost vs B0'],nom),'SHIFT_TABLE':mdtable(['Method','Burgers coefficient shift','Heat coefficient shift','Burgers delay/dropout','Heat delay/dropout'],shift),'LATENCY_TABLE':mdtable(['PDE','Method','Path','p50 ms','p99 ms','>5-ms requests','>5-ms rate'],lattable),'LATENCY_SEED_TABLE':mdtable(['PDE','Method','Seed','p50 ms','p95 ms','p99 ms','p99.9 ms','>5-ms count','>5-ms rate'],seedtable),'HASH_TABLE':mdtable(['Artifact','SHA-256'],[[r['path'],f"`{r['sha256']}`"] for r in hashes]),'COMMAND_TABLE':mdtable(['Stage','Historical exact entry-point command'],[[r['stage'],f"`{r['command']}`"] for r in command_rows])}
for file in [R/'manuscript_v3.md',O/'REPORT_KO.md',O/'REPRODUCE.md']:
 s=file.read_text(encoding='utf-8')
 for k,v in tables.items():s=s.replace('{{'+k+'}}',v)
 if '{{' in s:raise ValueError(f'Unresolved template: {file}')
 file.write_text(s,encoding='utf-8')
if not (O/'ledger_review_snapshot.md').exists():
 (O/'ledger_review_snapshot.md').write_bytes((R/'state/RUN_LEDGER.md').read_bytes())

claims=[]
def claim(cid,text,status,path,locator,support,caveat=''):
 p=R/path
 claims.append({'claim_id':cid,'claim':text,'status':status,'evidence_artifact':path,'evidence_locator':locator,'support_exact_json':json.dumps(support,ensure_ascii=False,allow_nan=False),'source_sha256':sha(p),'verification':'Independent raw reaggregation / source inspection as specified','scope_caveat':caveat})
claim('C001','Completed test comprises 1280 parents and 25600 controller executions.','VERIFIED','reports/analysis_20260928/audit.json','independent_test_parents;control_executions;raw_test_shards_read',{k:audit[k] for k in ('independent_test_parents','control_executions','raw_test_shards_read')},'Seeds and ticks are not additional independent parents.')
claim('C002','Host replay comprises 120 rows and 2400000 requests.','VERIFIED','reports/analysis_20260928/audit.json','latency_rows;latency_requests',{k:audit[k] for k in ('latency_rows','latency_requests')},'Repeated frozen observations; not independent environmental replicates.')
claim('C003','1694 numerical checks passed.','VERIFIED_ARITHMETIC_ONLY','reports/analysis_20260928/audit.json','status;arithmetic_checks;failed_checks',{'status':audit['status'],'checks':audit['arithmetic_checks'],'failures':audit['failed_checks']},'Not a measure of scientific effect, unit-test count, or independent experiments.')
claim('C004','All 24 selected operator field gates fail.','SUPPORTED_NEGATIVE','reports/source_audit.json','operator_checkpoints;failed_field_gates',{'total':24,'fail':24},'Validation result; not universal impossibility.')
for i,r in enumerate(cm['checkpoints']):
 if r['metadata'].get('validation'):
  claim(f'G2_{i:02d}',f"{r['pde']} {r['method']} seed {r['seed']} selected validation error",'G2_FAIL_RETAINED','evidence/confirmatory_checkpoint_manifest_v3.json',f'checkpoints[{i}].metadata.validation',r['metadata']['validation'],'Pooled all-candidate validation error; distinct from selected-action test diagnostic.')
for gi,g in enumerate(ca['groups']):
 for mi,m in enumerate(g['controller_metrics']):
  method=m['method'];claim(f'CONTROL_{gi}_{method}',f"{g['role']}/{g['pde']}/{method}: registered parent-averaged endpoints",'VERIFIED','evidence/locked_test_analysis_v3.json',f'groups[{gi}].controller_metrics[{mi}];groups[{gi}].paired_vs_h3_comparator.{method}',{'metrics':{k:v for k,v in m.items() if k!='seed_results'},'comparison':g['paired_vs_h3_comparator'][method]},'Cost denominator is the fixed observed comparator mean; fitted seeds averaged within parent; not original floored parent-wise estimand.')
 for label in ('P_vs_B5_cost_gap','B1_vs_B0_cost_gap'):
  claim(f'MATCHED_{gi}_{label}',f"{g['role']}/{g['pde']}/{label}",'VERIFIED','evidence/locked_test_analysis_v3.json',f'groups[{gi}].{label}',g[label],'Paired parent bootstrap conditional on fitted seeds; no equivalence conclusion from zero sample difference.')
for i,r in enumerate(la['controller_groups']):
 claim(f'LAT_SEED_{i:02d}',f"{r['pde']}/{r['method']}/seed={r['seed']} latency and deadline counts",'VERIFIED','evidence/latency_analysis_v3.json',f'controller_groups[{i}]',r,'Three sequential sessions; 60000 replay requests. p99.9 descriptive; no scheduled/extended-tail claim.')
for i,r in enumerate(lat):
 claim(f'LAT_POOL_{i:02d}',f"{r['pde']}/{r['method']} pooled descriptive latency",'DERIVED_VERIFIED','reports/analysis_20260928/latency_pooled_descriptive.csv',f'CSV row {i+2}',r,'Quantiles of concatenated raw arrays; different statistic from mean seed-specific H1 ratios.')
for i,r in enumerate(la['H1_p99_ratio_analysis']):
 claim(f'H1_{r["pde"]}',f"{r['pde']} P/B4 mean seed-specific p99 ratio",'MEANINGFUL_TARGET_NOT_MET','evidence/latency_analysis_v3.json',f'H1_p99_ratio_analysis[{i}]',r,'Target ratio <=0.75 and upper CI<1; three fitted seeds/three sequential sessions, not independent environments.')
for i,r in enumerate(js(R/'evidence/calibration_lock_v3.json')['groups']):
 claim(f'CAL_{i:02d}',f"{r['pde']}/{r['method']}/seed={r['seed']} passive forecast margin",'DIAGNOSTIC_ONLY','evidence/calibration_lock_v3.json',f'groups[{i}]',{k:v for k,v in r.items() if k!='parent_scores'},'Margin not used for action selection; no OOD, conditional harm, trajectory or uniform safety guarantee.')
claim('RISK_UNAVAILABLE','Conditional harm cannot be estimated without a frozen acceptance/correction gate.','NOT_ESTIMABLE','src/pdno/evaluation/closed_loop.py','policy_action;run_episode',{'acceptance_gate':False,'conditional_harm':None},'Absence is not zero risk; Darcy finite-family certificates do not apply.')
claim('HEAT_FIRST_STEP','All recorded heat any-time events are lower-bound events already at first advanced step.','POST_FREEZE_DIAGNOSTIC','reports/analysis_20260928/heat_constraint_diagnostic.csv','all 60 rows',{'nominal':{'first':351,'n':384,'initial_negative':356},'coefficient_ood':{'first':114,'n':128,'initial_negative':115},'delay_dropout':{'first':115,'n':128,'initial_negative':115},'upper_events':0,'late_new_events':0},'Registered endpoint/rates remain unchanged. Does not prove inevitability under every feasible control.')
claim('P_B5_ACTIONS','Burgers P/B5 saved action histories identical; heat differs in four parent-seed histories.','POST_FREEZE_DIAGNOSTIC','reports/analysis_20260928/P_B5_matched_actions.csv','all 18 rows',{'burgers_equal_parent_seed_histories':1920,'burgers_total':1920,'heat_equal':1916,'heat_total':1920},'These are matched parent-seed comparisons, not independent parent counts.')
claim('CUDA_LABELS','Original post-freeze CUDA p99 labels contain p99.9.','CORRECTED_DERIVED_SUMMARY','reports/cuda_diagnostic_correction.json','finding;rows',{'host_labels':16,'stream_labels':12,'ratios_and_deltas_correct':True},'Original preserved; registered latency analysis unaffected; new file is not a new benchmark.')
claim('CUDA_CORRECTION','Origin-task corrected CUDA assessment matches independent raw quantiles.','VERIFIED','evidence/cuda_runtime_assessment_v3_corrected.json','groups;correction',{'sha256':sha(R/'evidence/cuda_runtime_assessment_v3_corrected.json')},'Event-span/wall ratio does not establish GPU compute occupancy.')
claim('NUMERICS','Forced 200-tick numerical fixtures pass recorded thresholds.','RECORDED_PRETEST_EVIDENCE','evidence/deployed_solver_audit_v3.json','burgers;heat',js(R/'evidence/deployed_solver_audit_v3.json'),'Not rerun in final analysis; limited fixtures, not all-parent continuum accuracy guarantee.')
claim('RUNTIME','This final task actually ran gpt-6-astra xhigh.','LOCAL_RUNTIME_VERIFIED','reports/RUNTIME_METADATA.json','actual_model;actual_reasoning_effort;started_at_utc',js(O/'RUNTIME_METADATA.json'),'Applies only to this analysis/drafting task, not earlier experiments.')
claim('H3_NORMALIZATION','Executed normalization differs from original parent-wise floored work-order definition.','CONFIRMED_SCOPE_LIMIT','scripts/aggregate_locked_test_v3.py','cost_ratio expression',{'implemented':'(Jmethod_parent - Jcomparator_parent) / mean(Jcomparator_parent)','source_instruction':'section 14.1, parent-wise max(Jcomparator,epsilon_train)'},'No silent redefinition or retuned threshold; original exact estimand not certified.')
