claim('OBSERVATION_LIMIT','B0/B1 use less temporal information than learned policies from common causal object.','DISCLOSED_COMPARATOR_LIMIT','evidence/pretraining_spec_freeze_v3.json','feature_use_limitation',js(R/'evidence/pretraining_spec_freeze_v3.json')['feature_use_limitation'],'Equal raw availability does not imply equal feature utilization.')
with (O/'claim_evidence.csv').open('w',encoding='utf-8',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(claims[0]));w.writeheader();w.writerows(claims)

