writejson('table_provenance.json',{'tables':{k:hashlib.sha256(v.encode()).hexdigest() for k,v in tables.items()},'inputs':{str(f.relative_to(R)):sha(f) for f in [A/'control_all_methods.csv',A/'latency_pooled_descriptive.csv',A/'latency_per_seed.csv',R/'evidence/confirmatory_checkpoint_manifest_v3.json']},'rendering':'Tables rendered from independently audited numeric evidence, no manual numeric editing.'})
